mapper.select:
SELECT id, session_id, user_id, role, sources, content, created_at, updated_at
FROM chat_message
WHERE id = #{id}

SELECT id, session_id, user_id, role, sources, content, created_at, updated_at
FROM chat_message
WHERE session_id = #{sessionId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM chat_message
WHERE session_id = #{sessionId}

SELECT id, session_id, user_id, role, sources, content, created_at, updated_at
FROM chat_message
WHERE session_id = #{sessionId}
  AND created_at BETWEEN #{startTime} AND #{endTime}
ORDER BY created_at ASC
